import os, re

def parse_hex(s, fallback):
    s = (s or '').strip().lstrip('#')
    if not re.fullmatch(r'[0-9a-fA-F]{6}', s or ''):
        if re.fullmatch(r'[0-9a-fA-F]{3}', s or ''):
            s = ''.join(c * 2 for c in s)
        else:
            s = fallback
    return int(s[0:2], 16), int(s[2:4], 16), int(s[4:6], 16)

