def is_prime(x):
    if x < 2:
        return False
    if x < 4:
        return True
    if x % 2 == 0:
        return False
    i = 3
    while i * i <= x:
        if x % i == 0:
            return False
        i += 2
    return True

def sieve(limit):
    cap = 100000
    if limit > cap:
        limit = cap
    if limit < 2:
        return []
    flags = bytearray([1]) * (limit + 1)
    flags[0] = 0
    flags[1] = 0
    i = 2
    while i * i <= limit:
        if flags[i]:
            for j in range(i * i, limit + 1, i):
                flags[j] = 0
        i += 1
    return [k for k in range(2, limit + 1) if flags[k]]

def factorize(x):
    x = abs(x)
    if x < 2:
        return []
    factors = []
    d = 2
    while d * d <= x:
        while x % d == 0:
            factors.append(d)
            x //= d
        d += 1 if d == 2 else 2
    if x > 1:
        factors.append(x)
    return factors

