    if mode == 'list':
        primes = sieve(n)
        if not primes:
            print('no primes up to ' + str(n))
        else:
            print('primes up to ' + str(n) + ': ' + ', '.join(str(p) for p in primes))
    elif mode == 'factorize':
        if n < 2:
            print(str(n) + ' has no prime factorization')
            return
        factors = factorize(n)
        parts = []
        last = None
        count = 0
        for f in factors:
            if f == last:
                count += 1
            else:
                if last is not None:
                    parts.append(str(last) + ('^' + str(count) if count > 1 else ''))
                last = f
                count = 1
        if last is not None:
            parts.append(str(last) + ('^' + str(count) if count > 1 else ''))
        print(str(n) + ' = ' + ' x '.join(parts))
    else:
        print(str(n) + ' is ' + ('prime' if is_prime(n) else 'not prime') + ' (' + ('true' if is_prime(n) else 'false') + ')')

