src = os.environ.get('TEXT') or os.environ.get('INPUT') or os.environ.get('ARGS') or os.environ.get('MESSAGE') or ''
try:
    stop = {'a','an','the','and','or','but','of','in','on','to','for'}
    words = re.split(r'(\s+)', src.strip())
    tokens = [i for i, w in enumerate(words) if w.strip()]
    first = tokens[0] if tokens else -1
    last = tokens[-1] if tokens else -1
    out = []
    for i, w in enumerate(words):
        if not w.strip():
            out.append(w)
            continue
        lw = w.lower()
        if lw in stop and i != first and i != last:
            out.append(lw)
        else:
            out.append(w[0].upper() + w[1:].lower())
    print(''.join(out))
except Exception as e:
    print(src)

